    categories:["Twenty-Sixth Army","Red Army armies","Southwestern Front","Defense of Kiev","Operation Barbarossa"],
    facts:[["Formation represented","First formation"],["Formed","1940"],["Commander","Lieutenant General Fyodor Kostenko"],["Initial chief of staff","Major General Filipp Parusinov"],["Superior command","Southwestern Front"],["Initial sector","Przemyśl · Sambir"],["Initial rifle corps","8th Rifle Corps"],["Initial mobile force","8th Mechanized Corps"],["August role","Southern Kiev sector and counterattacks"],["Status on 31 August","Active"],["Later fate","Open"]]
